const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<i data-lucide="${n}"></i>`,fmt=n=>Number.isFinite(n)?Math.abs(n)>9999?n.toExponential(2):n.toFixed(3):'—';
const state={tabs:[],active:0,selected:'logistic',selectedEdge:null,selection:new Set(['logistic']),search:'',favorites:false,closed:new Set(['Math','Calculus','Combinatorics','Logic','Dynamics']),history:[],branches:[],panel:'history',panelClosed:false,filter:'all',zoom:1,pan:{x:0,y:0},tool:'select',pending:null,split:false,compare:1,source:false,sim:null,busy:false,clipboard:null};
const active=()=>state.tabs[state.active],model=()=>active().model;
let toastTimer,runTimer;
function toast(message){const e=$('#toast');e.textContent=message;e.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('visible'),3400);}
function refreshIcons(){createIcons({icons,attrs:{'aria-hidden':'true'}});}
function persist(){try{localStorage.setItem(('chaos-lab-tabs-v1'+repo.libraryKey),JSON.stringify({tabs:state.tabs.map(t=>({...t,undo:[],redo:[]})),active:state.active}));}catch{toast('Device storage is full. Export your repository to keep a backup.');}}
function edit(fn,rerender=true){const t=active();t.undo.push(clone(t.model));if(t.undo.length>60)t.undo.shift();t.redo=[];fn(t.model);t.dirty=true;persist();runSimulation();if(rerender)render();}
function effectiveR(n){const e=model().edges.find(e=>e.to===n.id&&e.port==='r');return e?model().nodes.find(n=>n.id===e.from)?.params.value:n.params.r;}
function runSimulation(){const start=performance.now();state.sim=compileModel(model());state.renderer=createDistributionRenderer();state.finalDraws=new Map();state.elapsed=performance.now()-start;}
const noStats={mean:NaN,sd:NaN,min:NaN,max:NaN,n:0};
function visualizeNode(id,compare=false){const analysis=compare?state.compareSim:state.sim,renderer=compare?state.compareRenderer:state.renderer;const law=analysis?.laws[id];return law?renderer.render(law,{resolution:model().renderResolution||512}):null;}

function button(action,label,ic,cls='icon-btn',extra=''){return `<button class="${cls}" data-action="${action}" title="${esc(label)}" aria-label="${esc(label)}" ${extra}>${ic?icon(ic):''}${cls.split(/\s+/).includes('btn')?esc(label):''}</button>`;}
function render(){
 const t=active(),m=t.model;
 $('#app').innerHTML=`<header class="topbar"><div class="brand"><img src="icon.svg" alt="Chaos Lab"><span>chaos<span>lab</span><sup style="font-size:8px;letter-spacing:0;margin-left:5px;color:#b1b9b0;font-weight:400">BETA</sup></span></div><nav class="topnav" aria-label="Main navigation"><button class="active" data-action="workspace">Workspace</button><button data-action="experiments">Experiments</button><button data-action="library">Block library</button></nav><div class="top-spacer"></div><span class="project-chip">PERSONAL WORKSPACE</span><button class="top-help" data-action="help">${icon('circle-help')}<span>Quick guide</span></button><div class="avatar" title="Your local workspace">Y</div></header>
 <div class="workspacebar"><div><div class="crumb">${icon('folder-open')}<button data-action="projects" class="muted">My workspace</button><span class="slash">/</span><button data-action="rename" class="model-title">${esc(m.name)}</button>${button('rename','Rename model','chevron-down')}</div><div class="saved-status"><span class="dot" style="${t.dirty?'background:#c2a471':''}"></span>${t.dirty?'Uncommitted changes':'All changes committed'}<span style="margin-left:5px;color:#bcc4bc">·</span><span class="mono" style="font-size:9px;margin-left:4px">${esc(m.branch)}</span></div></div><div class="actions"><div class="undo-actions">${button('undo','Undo · Ctrl Z','undo-2','icon-btn',t.undo.length?'':'disabled')}${button('redo','Redo · Ctrl Shift Z','redo-2','icon-btn',t.redo.length?'':'disabled')}</div><div class="divider"></div>${button('source','SysML','code-xml','btn source-action')}${button('save',state.busy?'Committing…':'Commit','git-commit-horizontal','btn outline',state.busy?'disabled':'')}${button('run','Render distributions','play','btn green')}</div></div>
 <div class="main-grid"><aside class="rail" aria-label="Workspace panels">${button('library','Block library','blocks','active')}${button('projects','Models','folder-open')}${button('git','Git history','git-branch')}${button('analytics','Distribution results','chart-no-axes-combined')}${button('source','SysML source','file-code-2')}<div class="bottom">${button('settings','Visualization settings','settings-2')}${button('help','Keyboard shortcuts','circle-help')}</div></aside>
 <aside class="library"><div class="library-head"><div class="section-title">Block library<span class="small-badge">${CATALOG.length}</span></div><p>A little structure. Infinite possibilities.</p><label class="searchbox">${icon('search')}<input id="block-search" placeholder="Search blocks…" aria-label="Search blocks" value="${esc(state.search)}"><kbd>/</kbd></label></div><div class="library-tabs"><button data-action="allblocks" class="${!state.favorites?'active':''}">All blocks</button><button data-action="favorites" class="${state.favorites?'active':''}">Favorites <span style="font-size:9px;margin-left:3px">☆</span></button></div><div class="categories" id="categories">${libraryHTML()}</div><div class="library-footer">${icon('mouse-pointer-2')}Drag a block onto the canvas</div></aside>
 <main class="center"><div class="tabs-bar"><div class="model-tabs">${state.tabs.map((tab,i)=>`<div class="model-tab ${state.active===i?'active':''}" data-tab="${i}" role="tab" aria-selected="${state.active===i}" tabindex="0">${icon('workflow')}<span>${esc(tab.model.name=== 'Logistic exploration'?'logistic_map':tab.model.name.replace(/ /g,'_').toLowerCase())}</span><span class="tab-branch">${esc(tab.model.branch)}</span>${tab.dirty?'<span style="color:#b39b78">•</span>':''}${state.tabs.length>1?`<button class="close-tab" data-close-tab="${i}" title="Close model tab">×</button>`:''}</div>`).join('')}</div>${button('new','New model','plus')}${button('split',state.split?'Merge view':'Split view','columns-2')}</div>
 <section class="canvas-wrap ${state.split?'split-mode':''}" id="canvas" aria-label="Visual model canvas"><div class="canvas-title"><strong>${state.split?'Compare designs':'A small equation. A world of chaos.'}</strong><p>${state.split?'Select a block on the right to copy it into your active model.':'Connect, experiment, and see what emerges.'}</p></div><div class="canvas-live"><span class="dot"></span>Symbolic probability laws<span style="color:#b8c4b7">|</span><span class="mono">CDF → visualization</span></div><div class="canvas-plane" id="plane" ${state.zoom!==1||state.pan.x||state.pan.y?`style="transform:translate(${state.pan.x}px,${state.pan.y}px) scale(${canvasScale()*state.zoom})"`:''}>${graphHTML(m)}</div><div class="canvas-toolbar">${button('select','Select · V','mouse-pointer-2',`icon-btn ${state.tool==='select'?'active':''}`)}${button('pan','Pan · H','hand',`icon-btn ${state.tool==='pan'?'active':''}`)}${button('tap','Add distribution tap · T','chart-no-axes-column-increasing',`icon-btn ${state.tool==='tap'?'active':''}`)}<div class="divider"></div>${button('zoomout','Zoom out','minus')}<span class="zoom-label mono">${Math.round(state.zoom*100)}%</span>${button('zoomin','Zoom in','plus')}${button('fit','Fit canvas','scan')}</div><div class="minimap" aria-hidden="true"><div class="view"></div>${m.nodes.map(n=>`<span class="mini-node" style="left:${n.x/9+6}px;top:${n.y/10+6}px;${n.type==='tap'?'width:25px;background:#c4d9c3':''}"></span>`).join('')}</div><div class="canvas-hint">${state.pending?'Select an input port to connect':state.tool==='tap'?'Click an input or output port to inspect':'Scroll to pan · Ctrl + scroll to zoom'}</div>${state.split?splitHTML():''}${state.source?sourceHTML():''}</section>
 <section class="git-panel ${state.gitExpanded?'expanded':''} ${state.panelClosed?'collapsed':''}"><div class="panel-header"><button class="panel-tab ${state.panel==='history'?'active':''}" data-action="git">${icon('git-branch')}Version history<span class="count">${state.history.length}</span></button><button class="panel-tab ${state.panel==='simulation'?'active':''}" data-action="analytics">${icon('activity')}Distributions</button><div class="panel-spacer"></div><span class="repo-local">${icon('hard-drive')}Local Git repository</span>${button('export','Export repository','download')}${button('expandgit',state.gitExpanded?'Restore panel':'Expand Git window','maximize-2')}${button('togglepanel',state.panelClosed?'Expand panel':'Collapse panel',state.panelClosed?'chevron-up':'chevron-down')}</div>${!state.panelClosed?`<div class="panel-content">${state.panel==='history'?historyHTML():simulationHTML()}</div>`:''}</section></main>
 <aside class="inspector" id="inspector">${inspectorHTML()}</aside></div><footer class="statusbar"><span>${icon('git-branch')}<span class="mono">${esc(m.branch)}</span></span><span><span class="dot"></span>${state.sim.errors.length?state.sim.errors.length+' model issue(s)':'Model ready'}</span><span class="optional">${icon('box')}${m.nodes.filter(n=>n.type!=='tap').length} blocks</span><span class="optional">${icon('cable')}${m.edges.length} connections</span><span class="spacer"></span><span class="optional">${icon('braces')}SysML 2.0 draft</span><span class="mono">CDF → visualization</span><span class="mono">${Math.max(1,state.elapsed).toFixed(0)} ms</span><span class="optional">${icon('shield-check')}Saved on this device</span></footer>`;
 refreshIcons();bindSearch();
}
function canvasScale(){if(innerWidth<=700)return .58;if(innerWidth<=1000)return .8;if(innerWidth<=1250)return .76;if(innerHeight<=830)return .76;return .88;}
function libraryHTML(){const groups=[...new Set(CATALOG.map(c=>c.category))],fav=['uniform','normal','logistic','custom','add','multiply','differentiate','integrate','tap','delay'];let found=0;const html=groups.map(group=>{const items=CATALOG.filter(c=>c.category===group&&(!state.favorites||fav.includes(c.op))&&`${c.name} ${c.category}`.toLowerCase().includes(state.search.toLowerCase()));if(!items.length)return '';found+=items.length;const closed=!state.search&&state.closed.has(group);return `<div class="category"><button class="category-title" data-category="${group}">${icon(closed?'chevron-right':'chevron-down')}${group}<span>${items.length}</span></button>${!closed?items.map(c=>`<div class="block-item ${c.type}" draggable="true" data-block="${c.op}" tabindex="0" role="button" title="Drag to canvas or double-click to add"><span class="block-symbol">${c.symbol}</span><span>${esc(c.name)}${['uniform','normal','logistic','custom'].includes(c.op)?`<small>${{uniform:'Evenly distributed values',normal:'The familiar bell curve',logistic:'r · x · (1 − x)',custom:'Your own expression'}[c.op]}</small>`:''}</span><span class="drag-dots">⠿</span></div>`).join(''):''}</div>`;}).join('');return found?html:'<div class="empty-library">No matching blocks.<br>Try “random” or “integrate”.</div>';}
function bindSearch(){$('#block-search').addEventListener('input',e=>{state.search=e.target.value;$('#categories').innerHTML=libraryHTML();refreshIcons();});}
function safeInputPorts(node){try{return inputPorts(node);}catch{return (node.inputPorts||[]).filter(p=>p&&p.name).map(p=>({...p,description:'Input '+p.name}));}}
function portY(node,name){if(['logistic','tent'].includes(node.op)&&name==='r')return 0;const ports=safeInputPorts(node).filter(p=>!(['logistic','tent'].includes(node.op)&&p.name==='r'));const index=ports.findIndex(p=>p.name===name);return (node.op==='custom'?88:70)+Math.max(0,index)*(node.op==='custom'?22:24);}
function nodeWidth(n){return n.type==='tap'?(n.id==='outputTap'||n.source?.id==='logistic'?280:227):n.op==='custom'||safeInputPorts(n).length>4?260:n.type==='function'?217:n.type==='delay'?165:177;}
function outPoint(n){return {x:n.x+nodeWidth(n),y:n.y+70};}
function inPoint(n,port='x'){return ['logistic','tent'].includes(n.op)&&port==='r'?{x:n.x+nodeWidth(n)/2,y:n.y}:{x:n.x,y:n.y+portY(n,port)};}
function curve(a,b){const dx=Math.max(35,Math.abs(b.x-a.x)*.45);return `M ${a.x} ${a.y} C ${a.x+dx} ${a.y}, ${b.x-dx} ${b.y}, ${b.x} ${b.y}`;}
function wirePath(a,b,e){const p=outPoint(a),q=inPoint(b,e.port);if(e.bend){const m=e.bend,dx=Math.max(25,Math.abs(m.x-p.x)*.4),ex=Math.max(25,Math.abs(q.x-m.x)*.4);return `M ${p.x} ${p.y} C ${p.x+dx} ${p.y}, ${m.x-dx} ${m.y}, ${m.x} ${m.y} C ${m.x+ex} ${m.y}, ${q.x-ex} ${q.y}, ${q.x} ${q.y}`;}
 if(e.port==='feedback')return `M ${p.x} ${p.y} L ${p.x+20} ${p.y} Q ${p.x+30} ${p.y} ${p.x+30} ${p.y+20} L ${p.x+30} ${p.y+80} Q ${p.x+30} ${p.y+90} ${p.x+20} ${p.y+90} L ${q.x-20} ${p.y+90} Q ${q.x-30} ${p.y+90} ${q.x-30} ${p.y+80} L ${q.x-30} ${q.y+20} Q ${q.x-30} ${q.y} ${q.x-20} ${q.y} L ${q.x} ${q.y}`;
 if(e.port==='r'&&['logistic','tent'].includes(b.op))return `M ${p.x} ${p.y} C ${p.x+35} ${p.y} ${q.x} ${q.y-20} ${q.x} ${q.y}`;
 return curve(p,q);
}
function graphHTML(m,compare=false){let wires=m.edges.map((e,index)=>{const a=m.nodes.find(n=>n.id===e.from),b=m.nodes.find(n=>n.id===e.to);if(!a||!b)return '';const path=wirePath(a,b,e),p=outPoint(a),q=inPoint(b,e.port),selected=!compare&&state.selectedEdge===index;return `<path class="wire ${e.port==='feedback'?'feedback':''} ${selected?'selected-wire':''}" d="${path}"/>${compare?'':`<path class="wire-hit" data-wire="${index}" d="${path}"><title>${esc(a.name)} output → ${esc(b.name)}.${esc(e.port)}. Drag the line to reroute; select it to drag either endpoint.</title></path>`}${selected?`<circle class="wire-handle" data-wire-end="from" data-edge="${index}" cx="${p.x}" cy="${p.y}" r="6"/><circle class="wire-handle" data-wire-end="to" data-edge="${index}" cx="${q.x}" cy="${q.y}" r="6"/>`:''}`;}).join('');
 for(const n of m.nodes.filter(n=>n.type==='tap'&&n.source)){const source=m.nodes.find(s=>s.id===n.source.id);if(!source)continue;const p=n.source.port==='in'?inPoint(source,n.source.inputPort||'x'):outPoint(source),q={x:n.x+nodeWidth(n)/2,y:n.y};wires+=`<path class="wire tap-wire" d="M ${p.x} ${p.y} L ${p.x+15} ${p.y} Q ${p.x+25} ${p.y} ${p.x+25} ${p.y+12} L ${p.x+25} ${q.y-28} Q ${p.x+25} ${q.y-17} ${p.x+12} ${q.y-17} L ${q.x+12} ${q.y-17} Q ${q.x} ${q.y-17} ${q.x} ${q.y}"/><circle class="wire-dot" cx="${p.x}" cy="${p.y}" r="2.4"/>`;}
 return `<svg class="wires" aria-label="Model connections">${wires}<path id="connection-ghost" class="connection-ghost" d=""/></svg>`+m.nodes.map(n=>nodeHTML(n,compare)).join('');}
const cloudCache = new WeakMap();
function cloudData(law, rendered, m, tap) {
  const field=meridianSpec(m,tap);
  const rate = cloudRate(law, rendered);
  if (!rendered || (!rate && !field)) return null;
  if (!cloudCache.has(rendered)) {
    let data;
    try {
      data=field?meridianData(field,m.samples,m.seed):{rate,points:positions(rendered,m.samples,m.seed),extent:4,view:'cloud'};
    } catch {return null;}
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = 192;
    drawOrbital(canvas, data);
    data.preview = canvas.toDataURL();
    cloudCache.set(rendered, data);
  }
  return cloudCache.get(rendered);
}

function orbitalPreview(node, rendered, m, compare) {
  if (!node.orbitalCloud && !node.meridian) return '';
  const analysis = compare ? state.compareSim : state.sim;
  const data = cloudData(analysis.laws[node.id], rendered, m,node);
  if (!data) return '<small>Cloud requires a Gamma radius with shape 3.</small>';
  return `<button class="orbital-preview" data-action="openorbital" data-tap="${esc(node.id)}" ${compare?'disabled':''}>
    <img src="${data.preview}" alt="Projected position measurements around the nucleus">
    <span>Orbital cloud ↗</span></button>`;
}

function openOrbital(element) {
  const id = element.dataset.tap;
  const data = cloudData(state.sim.laws[id], visualizeNode(id), model(),model().nodes.find(n=>n.id===id));
  if (!data) return;
  const body = `<div class="orbital-stage"><canvas width="520" height="520" aria-label="Electron position cloud around the nucleus"></canvas>
    <aside class="orbital-controls"><label>Spatial view<select id="orbital-view"><option value="cloud">Projected detections</option><option value="slice">Central density slice</option></select></label>
    <label>Field width<select id="orbital-width">${[.5,1,2].map(k=>`<option value="${data.extent*k}" ${k===1?'selected':''}>${2*data.extent*k} a₀</option>`).join('')}</select></label>
    <div class="orbital-key"><i></i> Nucleus</div><div class="orbital-ramp"></div><small>Low to high · square-root brightness</small>
    <p id="orbital-caption"></p></aside></div>`;
  modal('Orbital cloud', body, button('saveorbital','Save PNG','download','btn outline'), true);
  const dialog = $('.orbital-stage').closest('.modal');
  dialog.classList.add('orbital-dialog');
  function repaint() {
    const view = $('#orbital-view').value;
    const canvas = $('.orbital-stage canvas');
    canvas.setAttribute('aria-label', view==='slice'?'Central slice of spatial probability density':'Projected electron detections');
    drawOrbital(canvas,{...data,view,extent:Number($('#orbital-width').value)});
    $('#orbital-caption').textContent = data.density ? (view==='slice'?'Meridian density |ψ|² in the x–z plane. Brightness is relative to the peak in this window.':'Position detections projected onto x–z from the final density, using a finite radial and angular grid.') : view==='slice'
      ? 'Relative spatial density in the z = 0 plane. Its peak at the nucleus is 1.'
      : data.points.length.toLocaleString()+' positions from the final radial law, with isotropic directions, projected onto the x–y plane. Brightness shows local detection concentration.';
  }
  $('#orbital-view').value=data.view;
  $('#orbital-view').onchange = repaint;
  $('#orbital-width').onchange = repaint;
  repaint();
}

function nodeHTML(n,compare=false){const selected=!compare&&state.selection.has(n.id),m=compare?state.tabs[state.compare]?.model:model(),ports=safeInputPorts(n);let body='';
 if(n.type==='tap'){const v=visualizeNode(n.id,compare),s=v?.stats||noStats;return `<article class="node tap-node ${nodeWidth(n)===280?'output':''} ${selected?'selected':''}" data-node="${n.id}" ${compare?'data-compare-node="true"':''} style="left:${n.x}px;top:${n.y}px"><span class="tap-tag">${n.source?.port==='in'?'INPUT':'OUTPUT'} TAP · ${esc(m.nodes.find(s=>s.id===n.source?.id)?.name||'Unattached')}</span><div class="node-header">${icon('chart-no-axes-column-increasing')}<span class="node-title">${esc(n.name)}</span><span style="font-size:8px;color:#9cae9e">numerical CDF</span></div><div class="node-body">${orbitalPreview(n,v,m,compare)}${histogramSVG(v)}<div class="tap-stats"><span>μ ≈<b>${fmt(s.mean)}</b></span><span>σ ≈<b>${fmt(s.sd)}</b></span><span>bins<b>34</b></span></div></div><button class="port" data-port="tap" data-id="${n.id}" aria-label="Observation input: connect a distribution output" title="Observation input: connect a distribution output to visualize its law"></button></article>`;}
 if(n.type==='random')body=`<div class="node-detail"><span>${n.op==='uniform'?'Range':n.op==='normal'?'Mean / σ':'Distribution'}</span><span class="mono">${n.op==='uniform'?`[${n.params.min}, ${n.params.max}]`:n.op==='normal'?`${n.params.mean} / ${n.params.sigma}`:n.op}</span></div><div class="node-detail"><span>Representation</span><span class="mono">symbolic law</span></div>`;
 else if(n.type==='parameter')body=`<div class="node-detail"><span>Value</span><span class="mono" style="font-size:13px">${n.params.value}</span></div>`;
 else if(n.type==='delay')body='<div class="formula" style="font-size:15px">z⁻¹</div><div class="node-detail"><span>One iteration back</span><span class="mono">xₙ</span></div>';
 else if(n.op==='custom')body=`<div class="formula" title="${esc(n.params.expression)}">${esc(n.params.expression)}</div><div class="custom-port-list">${ports.map(p=>`<div class="custom-port-row"><b>${esc(p.label)}</b><span>${m.edges.some(e=>e.to===n.id&&e.port===p.name)?'connected':'default '+esc(p.default)}</span></div>`).join('')}${ports.length?'':'<div class="custom-port-row">Constant expression · no inputs</div>'}</div>`;
 else body=`<div class="formula">${n.op==='logistic'?(n.params.expression==='r*x*(1-x)'?'r · x · (1 − x)':esc(n.params.expression)):n.type==='calculus'?`${n.symbol} ${esc(n.params.expression)}`:n.type==='math'?`x ${n.symbol} b`:n.symbol+'(x)'}</div>`;
 const bodyHeight=n.op==='custom'?'auto':Math.max(55,...ports.map(p=>portY(n,p.name)-43+18));
 return `<article class="node ${n.type} ${n.op==='custom'?'custom':''} ${selected?'selected':''}" data-node="${n.id}" ${compare?'data-compare-node="true"':''} style="left:${n.x}px;top:${n.y}px;width:${nodeWidth(n)}px"><div class="node-header"><span class="node-icon">${n.symbol}</span><span class="node-title">${esc(n.name)}</span><span class="node-menu">···</span></div><div class="node-body" style="min-height:${bodyHeight==='auto'?'55px':bodyHeight+'px'}">${body}</div>${n.type!=='parameter'?`<div class="node-footer"><span>${{random:'PROBABILITY LAW',function:'SYMBOLIC FUNCTION',delay:'STATE / DELAY',calculus:'SYMBOLIC OPERATOR',math:'MATH OPERATOR',logic:'LOGIC OPERATOR',combinatorics:'COMBINATORICS'}[n.type]||n.type}</span><span>ℒ(X) → ℒ(Y)</span></div>`:''}${ports.map(p=>{const top=['logistic','tent'].includes(n.op)&&p.name==='r',y=portY(n,p.name);return `<button class="port in ${top?'top-input':''}" style="top:${y-5}px;left:${top?'calc(50% - 5px)':'-5px'}" data-port="${esc(p.name)}" data-id="${n.id}" aria-label="${esc(n.name)} input ${esc(p.name)}: ${esc(p.description)}" title="${esc(p.label)} — ${esc(p.description)} Default: ${esc(p.default)}"></button>${n.op==='custom'?'':`<span class="port-label ${top?'top-input-label':''}" style="top:${top?-19:y-5}px;left:${top?'calc(50% - 25px)':'9px'}">${esc(p.label)}</span>`}`;}).join('')}<button class="port out ${state.pending?.id===n.id?'pending':''}" data-port="out" data-id="${n.id}" aria-label="${esc(n.name)} output: resulting symbolic probability law" title="Output: resulting symbolic probability law. Drag to another block’s input."></button><span class="port-label right">${n.type==='delay'?'state':'result'}</span></article>`;
}
function histogramSVG(visual){
 if(!visual)return '<div class="law-pending">Attach a tap to a port to observe its symbolic law.</div>';
 if(visual.status!=='ready')return `<div class="law-pending"><b>Symbolic law retained</b><p>${esc(visual.error)}</p></div>`;
 const h=visual.histogram,max=Math.max(1e-15,...h.counts);
 return `<svg class="histogram" viewBox="0 0 240 87" preserveAspectRatio="none" role="img" aria-label="Final distribution: bin probability masses evaluated from the CDF"><title>${esc(visual.method)}</title><line x1="0" x2="240" y1="19" y2="19" class="axis-line" stroke-dasharray="2 3"/><line x1="0" x2="240" y1="43" y2="43" class="axis-line" stroke-dasharray="2 3"/>${h.counts.map((v,i)=>`<rect x="${i*7.05+.6}" y="${68-v/max*60}" width="5.5" height="${v/max*60}" rx=".7" fill="${i%3===0?'#86ab80':'#a1bd94'}" opacity="${.65+v/max*.3}"/>`).join('')}<line x1="0" x2="240" y1="68" y2="68" class="axis-line"/><text class="chart-axis" x="0" y="82">${h.min.toFixed(2)}</text><text class="chart-axis" x="112" y="82">${((h.min+h.max)/2).toFixed(2)}</text><text class="chart-axis" x="240" text-anchor="end" y="82">${h.max.toFixed(2)}</text></svg>`;
}
function historyHTML(){
 const logs=state.history.filter(c=>state.filter==='all'||c.branches.includes(state.filter)),lanes=['main',...new Set(logs.map(c=>c.branch).filter(b=>b!=='main'))],lane=c=>7+14*lanes.indexOf(c.branch),width=Math.max(38,lanes.length*14+7);
 const paths=logs.map((c,i)=>c.commit.parent.map(parent=>{const j=logs.findIndex(p=>p.oid===parent);if(j<0)return '';const x=lane(c),y=i*32+16,px=lane(logs[j]),py=j*32+16,mid=(y+py)/2;return `<path d="M ${x} ${y} C ${x} ${mid} ${px} ${mid} ${px} ${py}" fill="none" stroke="${c.branch==='main'?'#92b59b':'#b69acc'}" stroke-width="1.5"/>`;}).join('')).join('');
 return `<div class="git-controls">${icon('git-branch')}<select class="branch-select" id="branch-filter" aria-label="Filter Git branches"><option value="all">All branches</option>${state.branches.map(b=>`<option ${state.filter===b?'selected':''}>${esc(b)}</option>`).join('')}</select><button class="branch-button" data-action="newbranch">${icon('plus')}New branch</button><span class="right">Double-click a commit to open</span></div>${logs.map((c,i)=>{const exp=c.branch!=='main',selected=active().base===c.oid,labels=Object.entries(state.heads||{}).filter(([b,oid])=>oid===c.oid);return `<div class="commit-row ${selected?'selected':''}" data-commit="${c.oid}" tabindex="0" title="Double-click to open ${esc(c.commit.message.split('\n')[0])}"><svg class="tree" viewBox="0 ${i*32} ${width} 32" aria-hidden="true">${paths}<circle cx="${lane(c)}" cy="${i*32+16}" r="3.5" fill="${selected?'#76a486':'white'}" stroke="${exp?'#ad92c5':'#82aa8c'}" stroke-width="1.5"/></svg><span class="commit-title">${esc(c.commit.message.split('\n')[0])}</span>${labels.slice(0,2).map(([b])=>`<span class="branch-label ${b!=='main'?'purple':''}">${esc(b)}</span>`).join('')}<span class="commit-ref">${c.oid.slice(0,7)}</span><span class="commit-time">${relativeTime(c.commit.author.timestamp)}</span></div>`;}).join('')}`;
}
function relativeTime(ts){const mins=Math.max(0,Math.floor((Date.now()/1000-ts)/60));return mins<1?'just now':mins<60?mins+'m ago':Math.floor(mins/60)+'h ago';}
function inputField(key,label,value,type='number',extra=''){return `<div class="field"><label class="field-label" for="param-${key}">${label}</label><input class="field-input ${type==='text'?'':'mono'}" id="param-${key}" data-param="${key}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function inspectorHTML(){if(state.selectedEdge!==null&&model().edges[state.selectedEdge])return wireInspectorHTML();const n=model().nodes.find(n=>n.id===state.selected);if(!n)return `<div class="inspector-heading">Inspector</div><div class="empty">Select a block to explore its parameters.<br><br>Drag from the library to add your next idea.</div>`;const law=state.sim.laws[n.id],visual=visualizeNode(n.id),s=visual?.stats||noStats,expr=['function','calculus'].includes(n.type),r=effectiveR(n);let params='';
 if(['logistic','tent'].includes(n.op))params+=`<div class="field"><label class="field-label" for="growth-range">Growth rate <span class="unit">r</span></label><div class="range-line"><input id="growth-range" type="range" min="0" max="4" step="0.01" value="${r}" data-range="r" aria-label="Growth rate"><input class="number-input" aria-label="Growth rate value" data-param="r" type="number" step="0.01" value="${r}"></div><div class="range-scale"><span>0</span><span>2</span><span>4</span></div></div>`;
 if(expr)params+=`<div class="field"><label class="field-label" for="expression">Expression<span class="unit">ƒ(x)</span></label><div class="formula-input"><span>ƒ</span><input id="expression" class="field-input mono" data-param="expression" value="${esc(n.params.expression)}" spellcheck="false"></div><p class="field-help">${n.type==='calculus'?'Symbolic result':'∂ƒ / ∂x'} <code>${esc(symbolic(n.params.expression,n.op==='integrate'?'integrate':'differentiate'))}</code></p></div>`;
 if(n.type==='parameter')params+=inputField('value','Constant value',n.params.value,'number','step="0.01"');
 if(n.type==='random'){const keys=n.op==='uniform'?['min','max']:n.op==='normal'?['mean','sigma']:n.op==='gamma'?['shape','lambda']:n.op==='bernoulli'?['p']:n.op==='beta'?['a','b']:['lambda'];for(const k of keys)params+=inputField(k,{min:'Minimum',max:'Maximum',mean:'Mean · μ',sigma:'Standard deviation · σ',shape:'Shape · k',lambda:'Rate · λ',p:'Probability · p',a:'Alpha · α',b:'Beta · β'}[k],n.params[k],'number','step="0.1"');}
 if(n.type==='math'||n.type==='logic'||n.type==='combinatorics')params+=inputField('b','Second operand · b',n.params.b,'number','step="0.1"');
 if(n.op==='clamp')params+=inputField('min','Minimum',n.params.min)+inputField('max','Maximum',n.params.max);
 if(n.op==='switch')params+=inputField('p','Threshold',n.params.p)+inputField('a','If true',n.params.a)+inputField('b','If false',n.params.b);
 if(n.type==='delay')params=inputField('initial','Initial constant (when initial port is unconnected)',n.params.initial??'1/2','text')+'<p class="field-help">Stores the previous iteration. Route its output back to a function to create a feedback loop.</p>';
 if(n.type==='tap'){const observed=model().nodes.find(s=>s.id===n.source?.id);params=`<div class="field"><label class="field-label">Observe block</label><select class="field-input" id="tap-source"><option value="">Choose a block…</option>${model().nodes.filter(s=>s.type!=='tap').map(s=>`<option value="${s.id}" ${n.source?.id===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label class="field-label">Observe port</label><select class="field-input" id="tap-port"><option value="out" ${n.source?.port==='out'?'selected':''}>Output · result</option>${observed?safeInputPorts(observed).map(p=>`<option value="in:${esc(p.name)}" ${n.source?.port==='in'&&(n.source.inputPort||'x')===p.name?'selected':''}>Input · ${esc(p.label)}</option>`).join(''):''}</select></div>`;}

 if(n.type==='tap' && (cloudRate(law,visual)||n.orbitalCloud)) {
   params += `<label class="field"><input id="enable-orbital" type="checkbox" ${n.orbitalCloud?'checked':''}> Show isotropic orbital cloud (radius in a₀)</label>`;
 }
 const incoming=model().edges.filter(e=>e.to===n.id),outgoing=model().edges.filter(e=>e.from===n.id);
 return `<div class="inspector-heading">Block inspector${button('clearselect','Deselect block','panel-right-close')}</div><div class="inspector-section"><div class="selected-block"><div class="selected-block-icon">${n.symbol}</div><div><b>${esc(n.name)}</b><p>${{function:'Nonlinear function',random:'Random source',parameter:'Constant parameter',tap:'Distribution observer',calculus:'Symbolic operator',delay:'Discrete dynamics'}[n.type]||n.category+' operator'}</p></div></div></div><div class="inspector-section">${n.op==='custom'?customPortInspector(n):''}<h4>Parameters</h4>${params||'<p class="field-help">This block has no adjustable parameters.</p>'}</div><div class="inspector-section"><h4>Probability law</h4><code class="law-expression">${esc(law?.formula||'No resolved law')}</code><p class="field-help">${esc(visual?.method||visual?.error||'Symbolic distribution')}<br>${law?.sourceIds.length||0} independent source(s); shared wires retain identity.</p></div><div class="inspector-section"><h4>Connections <span style="float:right;font-size:8px">${incoming.length+outgoing.length}</span></h4>${incoming.map(e=>`<div class="connection-row"><span><span class="port-indicator"></span>${esc(e.port)}</span><span class="connection-value">${esc(model().nodes.find(s=>s.id===e.from)?.name)} <button data-disconnect="${e.from}|${e.to}|${e.port}" title="Disconnect wire" style="color:#b2beb3">×</button></span></div>`).join('')}${outgoing.length?`<div class="connection-row"><span><span class="port-indicator"></span>out</span><span class="connection-value">${outgoing.length} connection${outgoing.length>1?'s':''}</span></div>`:''}${!incoming.length&&!outgoing.length?'<p class="field-help">Connect ports to route a signal.</p>':''}${n.type!=='tap'?`<button class="tap-btn" data-action="tapselection">${icon('plus')}Add output distribution tap</button>`:''}</div><div class="inspector-section"><h4>Evaluated output statistics ≈ <span class="dot" style="float:right"></span></h4><div class="stat-grid"><div><small>MEAN · μ</small><span>${fmt(s.mean)}</span></div><div><small>STD. DEV · σ</small><span>${fmt(s.sd)}</span></div><div><small>DISPLAY MIN</small><span>${fmt(s.min)}</span></div><div><small>DISPLAY MAX</small><span>${fmt(s.max)}</span></div></div></div><div class="inspector-bottom"><div class="mode-badge">${icon('braces')}Symbolic engine · numerical visualization</div><div style="display:flex;gap:8px;margin-top:15px">${button('copy','Copy block','copy','btn soft')}${button('delete','Delete block','trash-2','icon-btn')}</div></div>`;}
function simulationHTML(){
 const n=model().nodes.find(n=>n.id===state.selected && n.type==='tap')||model().nodes.find(n=>n.op==='logistic')||model().nodes.find(n=>n.type==='function')||model().nodes.find(n=>n.type==='random');
 const visual=visualizeNode(n?.id),s=visual?.stats||noStats;
 if(!visual||visual.status!=='ready')return `<div class="empty">${esc(visual?.error||'Add a distribution source and a visualization tap.')}</div>`;
 const key=n.id+':'+model().samples+':'+model().seed;
 if(!state.finalDraws.has(key))state.finalDraws.set(key,sampleFinalDistribution(visual,model().samples,model().seed));
 const pts=state.finalDraws.get(key).slice(0,150),points=pts.map((x,i)=>`${i/(pts.length-1)*700},${75-(x-s.min)/(s.max-s.min||1)*65}`).join(' ');
 return `${state.sim.errors.length?`<div class="error-list">${state.sim.errors.map(esc).join('<br>')}</div>`:''}<div class="distribution-method">${esc(visual.method)}<br><span>Numerical visualization: CDF interpolation with ${visual.approximation.cdfInterpolationIntervals} intervals${visual.approximation.uncertifiedQuadratureError?' · quadrature error is not certified':''}${visual.approximation.momentQuadrature?' · moments approximated from bin masses':''}${visual.approximation.tailMass?' · tail window target ≈ '+visual.approximation.tailMass.toExponential(1)+' probability mass':''}.</span></div><div class="simulation-summary"><div>Final-law plot draws<b>${model().samples.toLocaleString()}</b></div><div>Symbolic iterations<b>${state.sim.iterations}</b></div><div>Evaluated mean ≈<b>${fmt(s.mean)}</b></div><div>Compilation<b>${Math.max(1,state.elapsed).toFixed(0)}<small style="font-size:10px"> ms</small></b></div><div style="margin-left:auto">${button('settings','Configure','sliders-horizontal','btn outline')}</div></div><svg class="analysis-graph" viewBox="0 0 700 90" preserveAspectRatio="none" role="img" aria-label="Independent visualization draws from the final evaluated CDF"><path d="M 0 25 H 700 M 0 50 H 700 M 0 75 H 700" stroke="#e5ece1" fill="none" stroke-dasharray="3 4"/><polyline points="${points}" fill="none" stroke="#79a785" stroke-width="1"/><text x="0" y="89" class="chart-axis">Final-law draw 1</text><text x="600" y="89" class="chart-axis">Draw ${pts.length}</text></svg>`;
}
function sourceHTML(){return `<div class="source-view"><div class="source-header">${icon('file-code-2')}<strong>model.sysml</strong><span class="note">Generated SysML 2.0 draft</span>${button('downloadsysml','Export','download','btn outline')}${button('source','Close source','x')}</div><p class="note">Editable graph is stored alongside this representation in model.json. Full SysML semantic validation is pending.</p><pre>${esc(toSysML(model()))}</pre></div>`;}
function splitHTML(){if(state.compare===state.active)state.compare=state.tabs.findIndex((_,i)=>i!==state.active);const t=state.tabs[state.compare];if(!t)return `<div class="split-container"><div class="split-title">Compare model${button('split','Merge view','x')}</div><div class="split-empty">Double-click any commit in version history to open another model, then split the view.</div></div>`;state.compareSim=compileModel(t.model);state.compareRenderer=createDistributionRenderer();return `<div class="split-container"><div class="split-title"><select class="branch-select" id="compare-tab" aria-label="Comparison model">${state.tabs.map((t,i)=>i!==state.active?`<option value="${i}" ${i===state.compare?'selected':''}>${esc(t.model.name)} · ${esc(t.model.branch)}</option>`:'').join('')}</select>${button('split','Merge view','x')}</div><div class="split-content" style="transform:scale(.52);width:820px">${graphHTML(t.model,true)}</div><div class="split-empty" style="padding-top:0;font-size:9px">Click a block above to copy it. Paste into the active design with Ctrl V.</div></div>`;}
function modal(title,content,actions='',large=false){$('#modal-root').innerHTML=`<div class="modal-overlay"><div class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${esc(title)}</h2>${content}<div class="modal-actions">${button('closemodal','Close',null,'btn outline')}${actions}</div></div></div>`;refreshIcons();setTimeout(()=>$('.modal input')?.focus(),30);}
function closeModal(){$('#modal-root').innerHTML='';}
function addBlock(op,x,y){edit(m=>{const n=makeNode(op,Math.max(10,x??180),Math.max(0,y??120));if(op==='tap'){n.name='Distribution tap';n.source=state.selected?{id:state.selected,port:'out'}:null;}m.nodes.push(n);state.selected=n.id;state.selection=new Set([n.id]);});toast('Block added · connect its ports to route a signal');}
function addTap(id,port='out'){const n=model().nodes.find(n=>n.id===id);if(!n||n.type==='tap')return;edit(m=>{const tap=makeNode('tap',n.x,Math.max(n.y+($('#plane [data-node="'+n.id+'"]')?.offsetHeight||150)+50,340));tap.name=port==='out'?'Output distribution':'Input '+(port==='in'?'x':port)+' distribution';tap.source=port==='out'?{id,port:'out'}:{id,port:'in',inputPort:port==='in'?'x':port};m.nodes.push(tap);state.selected=tap.id;state.selection=new Set([tap.id]);});state.tool='select';render();toast(`${port==='out'?'Output':'Input'} distribution tap attached`);}
async function refreshRepository(){[state.history,state.branches]=await Promise.all([repo.history(),repo.branches()]);state.heads=Object.fromEntries(await Promise.all(state.branches.map(async b=>[b,await repo.head(b)])));}
async function save(){
 if(state.busy)return;state.busy=true;const t=active(),snapshot=clone(t.model);render();
 try{let branch=snapshot.branch,head;try{head=await repo.head(branch);}catch{}if(head&&head!==t.base){branch='exploration-'+Date.now().toString(36);await repo.newBranch(branch,t.base);snapshot.branch=branch;t.model.branch=branch;}
 t.base=await repo.commitModel(snapshot,branch,snapshot.name);t.dirty=JSON.stringify(t.model)!==JSON.stringify(snapshot);await refreshRepository();persist();toast(`Committed ${t.base.slice(0,7)} on ${branch}`);
 }catch(e){toast('Could not commit: '+e.message);}finally{state.busy=false;render();}
}
async function openCommit(oid){try{const existing=state.tabs.findIndex(t=>t.base===oid&&!t.dirty);if(existing>=0){state.active=existing;}else{const m=await repo.readModel(oid);state.tabs.push({model:m,base:oid,dirty:false,undo:[],redo:[]});state.active=state.tabs.length-1;}state.selectedEdge=null;state.selected=model().nodes.find(n=>n.op==='logistic')?.id||model().nodes[0]?.id;state.selection=new Set([state.selected]);state.pan={x:0,y:0};state.zoom=1;state.source=false;runSimulation();persist();render();toast('Commit opened in a model tab');}catch(e){toast('Could not open commit: '+e.message);}}
function undo(redo=false){const t=active(),from=redo?t.redo:t.undo,to=redo?t.undo:t.redo;if(!from.length)return;to.push(clone(t.model));t.model=from.pop();t.dirty=true;persist();runSimulation();render();}
function copyNodes(compareId){const m=compareId?state.tabs[state.compare].model:model(),ids=compareId?new Set([compareId]):state.selection;const nodes=m.nodes.filter(n=>ids.has(n.id));if(!nodes.length)return;state.clipboard={nodes:clone(nodes),edges:clone(m.edges.filter(e=>ids.has(e.from)&&ids.has(e.to)))};toast(`${nodes.length} block${nodes.length>1?'s':''} copied · paste into any model tab`);}
function paste(){if(!state.clipboard)return toast('Select a block and copy it first');edit(m=>{const map=new Map();const nodes=state.clipboard.nodes.map(n=>{const next=clone(n),id='n'+crypto.randomUUID().slice(0,8);map.set(n.id,id);return {...next,id,x:next.x+35,y:next.y+35};});for(const n of nodes)if(n.source)n.source=map.has(n.source.id)?{...n.source,id:map.get(n.source.id)}:m.nodes.some(s=>s.id===n.source.id)?n.source:null;m.nodes.push(...nodes);m.edges.push(...state.clipboard.edges.map(e=>({...e,from:map.get(e.from),to:map.get(e.to)})));state.selection=new Set(nodes.map(n=>n.id));state.selected=nodes[0]?.id;});toast('Pasted into '+model().name);}
function deleteSelected(){if(state.selectedEdge!==null){edit(m=>m.edges.splice(state.selectedEdge,1));state.selectedEdge=null;render();return;}if(!state.selection.size)return;edit(m=>{m.nodes=m.nodes.filter(n=>!state.selection.has(n.id));m.edges=m.edges.filter(e=>!state.selection.has(e.from)&&!state.selection.has(e.to));for(const n of m.nodes)if(n.source&&state.selection.has(n.source.id))n.source=null;state.selection.clear();state.selected=null;});}
function download(data,name,type='text/plain'){const blob=data instanceof Blob?data:new Blob([data],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
