function switchTab(index){state.selectedEdge=null;if(index<0||index>=state.tabs.length)return;state.active=index;state.selected=state.tabs[index].model.nodes.find(n=>n.id==='logistic')?.id||state.tabs[index].model.nodes[0]?.id;state.selection=new Set(state.selected?[state.selected]:[]);state.pending=null;state.pan={x:0,y:0};state.zoom=1;state.source=false;runSimulation();persist();render();}
function onPort(el){const id=el.dataset.id,port=el.dataset.port;if(state.tool==='tap'&&port!=='tap')return addTap(id,port);if(port==='out'){state.pending={id};render();toast('Drag or click a named input port to connect');return;}if(state.pending)connectPorts(state.pending.id,id,port);else toast('Drag from an output to this input, or click an output first.');}
document.addEventListener('click',async e=>{
 if(performance.now()<(state.ignoreCanvasClickUntil||0)&&state.ignoreCanvasClickPoint&&Math.hypot(e.clientX-state.ignoreCanvasClickPoint.x,e.clientY-state.ignoreCanvasClickPoint.y)<5&&e.target.closest('#canvas'))return;
 const action=e.target.closest('[data-action]');if(action){const fn=actions[action.dataset.action];if(fn)try{await fn(action);}catch(err){toast(err.message);}return;}
 if(e.target.classList.contains('modal-overlay'))return closeModal();
 const close=e.target.closest('[data-close-tab]');if(close){const i=+close.dataset.closeTab;if(state.tabs[i].dirty){const archive=JSON.parse(localStorage.getItem(('chaos-lab-drafts-v1'+repo.libraryKey))||'[]');archive.push(state.tabs[i]);localStorage.setItem(('chaos-lab-drafts-v1'+repo.libraryKey),JSON.stringify(archive.slice(-20)));toast('Uncommitted model retained in drafts');}state.tabs.splice(i,1);state.active=Math.min(state.active,state.tabs.length-1);switchTab(state.active);return;}
 const tab=e.target.closest('[data-tab]');if(tab)return switchTab(+tab.dataset.tab);
 const draft=e.target.closest('[data-restore-draft]');if(draft){const drafts=JSON.parse(localStorage.getItem(('chaos-lab-drafts-v1'+repo.libraryKey))||'[]'),t=drafts.splice(+draft.dataset.restoreDraft,1)[0];localStorage.setItem(('chaos-lab-drafts-v1'+repo.libraryKey),JSON.stringify(drafts));state.tabs.push({...t,undo:[],redo:[]});closeModal();switchTab(state.tabs.length-1);return;}
 const open=e.target.closest('[data-open-tab]');if(open){closeModal();return switchTab(+open.dataset.openTab);}
 const commit=e.target.closest('[data-open-commit]');if(commit){closeModal();return openCommit(commit.dataset.openCommit);}
 const category=e.target.closest('[data-category]');if(category){const g=category.dataset.category;state.closed.has(g)?state.closed.delete(g):state.closed.add(g);$('#categories').innerHTML=libraryHTML();refreshIcons();return;}
 const port=e.target.closest('[data-port]');if(port){if(port.closest('.split-container'))return;return onPort(port);}
 const disconnect=e.target.closest('[data-disconnect]');if(disconnect){const [from,to,port]=disconnect.dataset.disconnect.split('|');edit(m=>m.edges=m.edges.filter(e=>!(e.from===from&&e.to===to&&e.port===port)));return;}
 const compare=e.target.closest('[data-compare-node]');if(compare)return copyNodes(compare.dataset.node);
 const node=e.target.closest('[data-node]');if(node){if(state.justDragged){state.justDragged=false;return;}const id=node.dataset.node;state.selectedEdge=null;if(e.shiftKey||e.ctrlKey||e.metaKey){state.selection.has(id)?state.selection.delete(id):state.selection.add(id);}else state.selection=new Set([id]);state.selected=id;$('#plane').innerHTML=graphHTML(model());$('#inspector').innerHTML=inspectorHTML();refreshIcons();return;}
 if(e.target.id==='canvas'||e.target.id==='plane'){state.pending=null;if(state.tool==='select'){state.selection.clear();state.selected=null;render();}}
});
document.addEventListener('dblclick',e=>{const block=e.target.closest('[data-block]');if(block)return addBlock(block.dataset.block,100+Math.random()*300,80+Math.random()*150);const commit=e.target.closest('[data-commit]');if(commit)return openCommit(commit.dataset.commit);});
document.addEventListener('keydown',e=>{
 const typing=/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName),mod=e.ctrlKey||e.metaKey;
 if(e.key==='Escape'){state.pending=null;state.tool='select';if($('#modal-root').innerHTML)closeModal();else{state.source=false;render();}return;}
 if(typing){if(e.key==='Enter'&&$('.modal')){const submit=$('.modal-actions .green');submit?.click();}return;}
 if(e.key==='Enter'){const c=e.target.closest('[data-commit]'),b=e.target.closest('[data-block]'),t=e.target.closest('[data-tab]');if(c)openCommit(c.dataset.commit);if(b)addBlock(b.dataset.block);if(t)switchTab(+t.dataset.tab);return;}
 if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();save();return;}if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();undo(true);return;}if(mod&&e.key.toLowerCase()==='c'){e.preventDefault();copyNodes();return;}if(mod&&e.key.toLowerCase()==='v'){e.preventDefault();paste();return;}if(mod&&e.key.toLowerCase()==='a'){e.preventDefault();state.selection=new Set(model().nodes.map(n=>n.id));render();return;}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected();return;}if(e.key==='/'){e.preventDefault();$('#block-search')?.focus();return;}if(e.key.toLowerCase()==='t')actions.tap();if(e.key.toLowerCase()==='h')actions.pan();if(e.key.toLowerCase()==='v')actions.select();
});
function updateParam(key,value,renderNow=true){if(key==='initial'){try{scalar(value);}catch(error){toast(error.message);return;}}const n=model().nodes.find(n=>n.id===state.selected);if(!n)return;const current=n.params;if(!['expression','initial'].includes(key)&&!Number.isFinite(+value))return toast('Enter a finite number');if(['shape','sigma'].includes(key)&&+value<=0||key==='lambda'&&+value<=0||['a','b'].includes(key)&&n.op==='beta'&&(+value<=0))return toast('Enter a positive value.');if(key==='p'&&(value<0||value>1))return toast('Probability must be between 0 and 1');if(key==='min'&&+value>=current.max||key==='max'&&+value<=current.min)return toast('Maximum must be greater than minimum');edit(m=>{if(key==='r'){const e=m.edges.find(e=>e.to===n.id&&e.port==='r'),param=m.nodes.find(n=>n.id===e?.from);if(param?.type==='parameter')param.params.value=+value;else m.nodes.find(s=>s.id===n.id).params.r=+value;}else m.nodes.find(s=>s.id===n.id).params[key]=['expression','initial'].includes(key)?value:+value;if(key==='expression'&&n.op==='custom'&&n.portMode!=='manual'){try{const target=m.nodes.find(s=>s.id===n.id);target.inputPorts=customInputPorts(target);const names=target.inputPorts.map(p=>p.name);m.edges=m.edges.filter(e=>e.to!==n.id||names.includes(e.port));}catch{}}},renderNow);}
document.addEventListener('change',e=>{const el=e.target;if(el.id==='enable-orbital'){edit(m=>m.nodes.find(n=>n.id===state.selected).orbitalCloud=el.checked);return;}if(el.dataset.param)return updateParam(el.dataset.param,el.value);if(el.id==='branch-filter'){state.filter=el.value;render();}if(el.id==='compare-tab'){state.compare=+el.value;render();}if(el.id==='tap-source'||el.id==='tap-port'){const source=$('#tap-source').value,port=el.id==='tap-source'?'out':$('#tap-port').value;edit(m=>m.nodes.find(n=>n.id===state.selected).source=source?(port==='out'?{id:source,port:'out'}:{id:source,port:'in',inputPort:port.slice(3)}):null);}});
let rangeStart;
document.addEventListener('pointerdown',e=>{if(e.target.dataset.range)rangeStart=clone(model());});
document.addEventListener('input',e=>{if(e.target.dataset.range){const n=model().nodes.find(n=>n.id===state.selected);const edge=model().edges.find(e=>e.to===n.id&&e.port==='r'),param=model().nodes.find(n=>n.id===edge?.from);if(param?.type==='parameter')param.params.value=+e.target.value;else n.params.r=+e.target.value;active().dirty=true;clearTimeout(runTimer);runTimer=setTimeout(()=>{runSimulation();$('#plane').innerHTML=graphHTML(model());const number=$('[data-param="r"]');if(number)number.value=e.target.value;refreshIcons();persist();},45);}});
document.addEventListener('pointerup',e=>{if(rangeStart){active().undo.push(rangeStart);active().redo=[];rangeStart=null;persist();clearTimeout(runTimer);runSimulation();render();}});
document.addEventListener('dragstart',e=>{const block=e.target.closest('[data-block]');if(block){e.dataTransfer.setData('application/chaos-block',block.dataset.block);e.dataTransfer.effectAllowed='copy';}});
document.addEventListener('dragover',e=>{if(e.target.closest('#canvas')&&!e.target.closest('.split-container')){e.preventDefault();e.dataTransfer.dropEffect='copy';}});
document.addEventListener('drop',e=>{if(!e.target.closest('#canvas'))return;e.preventDefault();const op=e.dataTransfer.getData('application/chaos-block');if(!op)return;const rect=$('#plane').getBoundingClientRect(),scale=rect.width/820;addBlock(op,(e.clientX-rect.left)/scale-70,(e.clientY-rect.top)/scale-20);});
document.addEventListener('pointerdown',e=>{
 if(e.button!==0||e.target.closest('button,input,select,.source-view,.split-container'))return;
 const node=e.target.closest('#plane [data-node]'),canvas=e.target.closest('#canvas');if(!canvas)return;
 const panning=state.tool==='pan'||e.altKey;if(!node&&!panning)return;
 const start={x:e.clientX,y:e.clientY},before=clone(model()),scale=$('#plane').getBoundingClientRect().width/820,n=node?model().nodes.find(n=>n.id===node.dataset.node):null,positions=new Map(model().nodes.filter(s=>state.selection.has(n?.id)?state.selection.has(s.id):s.id===n?.id).map(s=>[s.id,{x:s.x,y:s.y}])),pan={...state.pan};let moved=false;
 function move(ev){const dx=(ev.clientX-start.x)/scale,dy=(ev.clientY-start.y)/scale;if(Math.abs(dx)+Math.abs(dy)<3)return;moved=true;if(panning){state.pan={x:pan.x+ev.clientX-start.x,y:pan.y+ev.clientY-start.y};$('#plane').style.transform=`translate(${state.pan.x}px,${state.pan.y}px) scale(${canvasScale()*state.zoom})`;}else{for(const [id,pos]of positions){const target=model().nodes.find(s=>s.id===id);target.x=Math.max(0,pos.x+dx);target.y=Math.max(0,pos.y+dy);}$('#plane').innerHTML=graphHTML(model());refreshIcons();}}
 function up(){document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);if(moved&&!panning){active().undo.push(before);active().redo=[];active().dirty=true;persist();state.justDragged=true;setTimeout(()=>state.justDragged=false,100);render();}}
 document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);
});
document.addEventListener('wheel',e=>{if(!e.target.closest('#canvas')||e.target.closest('.source-view,.split-container'))return;e.preventDefault();if(e.ctrlKey||e.metaKey){state.zoom=Math.max(.35,Math.min(1.8,state.zoom-e.deltaY*.002));}else{state.pan.x-=e.deltaX;state.pan.y-=e.deltaY;}$('#plane').style.transform=`translate(${state.pan.x}px,${state.pan.y}px) scale(${canvasScale()*state.zoom})`;$('.zoom-label').textContent=Math.round(state.zoom*100)+'%';},{passive:false});
window.addEventListener('resize',()=>{if(state.tabs.length)render();});
async function boot(){try{const main=await repo.initRepository();await refreshRepository();let stored;try{stored=JSON.parse(localStorage.getItem(('chaos-lab-tabs-v1'+repo.libraryKey)));}catch{}if(stored?.tabs?.length){state.tabs=stored.tabs.map(t=>({...t,undo:[],redo:[]}));state.active=Math.min(stored.active||0,state.tabs.length-1);}else if(repo.libraryKey){const m=await repo.readModel(main);state.tabs=[{model:m,base:main,dirty:false,undo:[],redo:[]}];state.selected=m.nodes[0]?.id;state.selection=new Set([state.selected]);}else{const m=await repo.readModel(main),branch=await repo.head('edge-of-chaos'),experiment=await repo.readModel(branch);state.tabs=[{model:m,base:main,dirty:false,undo:[],redo:[]},{model:experiment,base:branch,dirty:false,undo:[],redo:[]}];}runSimulation();render();window.chaosLab={getState:()=>state,repo,compileModel,createDistributionRenderer};}catch(e){$('#app').innerHTML=`<div class="boot"><div class="boot-logo">∿</div><strong>Could not open the local repository.</strong><span>${esc(e.message)}</span><p>Enable browser storage and reload to start your workspace.</p><button class="btn outline" onclick="location.reload()">Try again</button></div>`;console.error(e);}}
function customPortInspector(n){const ports=safeInputPorts(n);return `<div class="custom-ports-inspector"><h4>Input ports <span class="small-badge">${ports.length}</span></h4><p class="field-help">${n.portMode==='manual'?'Manual input list':'Inferred from the expression'}. Names are function arguments. Defaults are constants used when no wire is attached.</p><div class="custom-port-fields">${ports.map((p,i)=>`<div class="custom-port-field"><input aria-label="Input ${i+1} name" data-custom-port-index="${i}" data-custom-port-field="name" value="${esc(p.name)}" title="Variable name in the expression"><input aria-label="Default for ${esc(p.name)}" data-custom-port-index="${i}" data-custom-port-field="default" value="${esc(p.default)}" title="Default constant for unconnected ${esc(p.name)}">${button('removeinput','Remove input','x','icon-btn',`data-port-index="${i}"`)}</div>`).join('')}</div><div class="port-actions">${button('addinput','Add input','plus','btn soft')}${button('syncinputs','Infer from expression','refresh-cw','btn outline')}</div></div>`;}
function wireInspectorHTML(){const edge=model().edges[state.selectedEdge],from=model().nodes.find(n=>n.id===edge.from),to=model().nodes.find(n=>n.id===edge.to);return `<div class="inspector-heading">Connection inspector${button('clearwire','Deselect connection','x')}</div><div class="inspector-section"><h4>Signal path</h4><p class="wire-description"><b>${esc(from?.name)}</b><br>result → <b>${esc(to?.name)}.${esc(edge.port)}</b></p><p class="field-help">This wire carries the same symbolic random variable. It does not create an independent draw.</p></div><div class="inspector-section"><h4>Edit connection</h4><p class="field-help">Drag the line to change its route. Drag either round endpoint handle to reconnect it to another port. Drop on empty canvas to cancel.</p><div class="port-actions">${button('resetwire','Reset route','rotate-ccw','btn outline')}${button('delete','Disconnect','unplug','btn outline')}</div></div>`;}
function connectPorts(from,to,port,rewireIndex=null){const a=model().nodes.find(n=>n.id===from),b=model().nodes.find(n=>n.id===to);if(!a||!b)return false;if(from===to&&a.type!=='delay'){toast('Use a Unit delay for a feedback loop.');return false;}
 if(port==='tap'&&b.type==='tap'){state.pending=null;edit(m=>m.nodes.find(n=>n.id===to).source={id:from,port:'out'});toast('Visualization tap connected');return true;}
 if(!safeInputPorts(b).some(p=>p.name===port)){toast('Choose a named input port.');return false;}
 if(port==='feedback'&&['logistic','tent'].includes(b.op)&&a.type!=='delay'){toast('The previous-state port expects a Unit delay output.');return false;}
 state.pending=null;edit(m=>{const previous=rewireIndex!==null?m.edges[rewireIndex]:null;const next={...(previous||{}),from,to,port};m.edges=m.edges.filter((edge,index)=>index!==rewireIndex&&!(edge.to===to&&edge.port===port));m.edges.push(next);if(rewireIndex!==null){state.selectedEdge=m.edges.length-1;state.selected=null;state.selection.clear();}});toast(`${a.name}.result → ${b.name}.${port}`);return true;
}
Object.assign(actions,{
 addinput(){const n=model().nodes.find(n=>n.id===state.selected);if(n?.op!=='custom')return;edit(m=>{const target=m.nodes.find(s=>s.id===n.id),ports=safeInputPorts(target);let i=1;while(ports.some(p=>p.name==='input'+i))i++;target.inputPorts=[...ports,{name:'input'+i,label:'input'+i,default:'0'}];target.portMode='manual';});},
 removeinput(element){const n=model().nodes.find(n=>n.id===state.selected),index=+element.dataset.portIndex;if(n?.op!=='custom')return;edit(m=>{const target=m.nodes.find(s=>s.id===n.id),ports=safeInputPorts(target),removed=ports.splice(index,1)[0];target.inputPorts=ports;target.portMode='manual';m.edges=m.edges.filter(e=>e.to!==n.id||e.port!==removed.name);for(const tap of m.nodes)if(tap.source?.id===n.id&&tap.source?.inputPort===removed.name)tap.source=null;});},
 syncinputs(){const n=model().nodes.find(n=>n.id===state.selected);if(n?.op!=='custom')return;try{const ports=customInputPorts({...n,portMode:'auto'});edit(m=>{const target=m.nodes.find(s=>s.id===n.id);target.portMode='auto';target.inputPorts=ports;m.edges=m.edges.filter(e=>e.to!==n.id||ports.some(p=>p.name===e.port));});toast('Input ports synchronized with expression variables');}catch(error){toast(error.message);}},
 clearwire(){state.selectedEdge=null;render();},resetwire(){if(state.selectedEdge!==null)edit(m=>delete m.edges[state.selectedEdge].bend);}
});

document.addEventListener('change',event=>{
 const el=event.target;if(el.dataset.customPortIndex===undefined)return;
 const n=model().nodes.find(n=>n.id===state.selected);if(n?.op!=='custom')return;
 const ports=safeInputPorts(n),index=+el.dataset.customPortIndex,field=el.dataset.customPortField,value=el.value.trim(),old=ports[index]?.name;
 try{
  if(field==='name'){validatePortName(value);if(ports.some((p,i)=>i!==index&&p.name===value))throw Error('Input names must be unique.');}else scalar(value);
  edit(m=>{const target=m.nodes.find(s=>s.id===n.id);target.inputPorts=ports.map(p=>({...p}));target.portMode='manual';target.inputPorts[index][field]=value;
   if(field==='name'){target.inputPorts[index].label=value;target.params.expression=target.params.expression.replace(new RegExp('\\b'+old+'\\b','g'),value);for(const e of m.edges)if(e.to===n.id&&e.port===old)e.port=value;for(const tap of m.nodes)if(tap.source?.id===n.id&&tap.source.inputPort===old)tap.source.inputPort=value;}
  });
 }catch(error){toast(error.message);render();}
});

// Pointer gestures use real port hit testing. Original wires remain intact until
// a successful drop, so cancelling or missing a target never discards a design.
document.addEventListener('pointerdown',event=>{
 if(event.button!==0||event.target.closest('.split-container,.source-view')||state.tool==='tap'||state.tool==='pan')return;
 const port=event.target.closest('[data-port]'),handle=event.target.closest('[data-wire-end]'),line=event.target.closest('[data-wire]');
 if(!port&&!handle&&!line)return;
 const before=clone(model()),start={x:event.clientX,y:event.clientY};let moved=false,mode,index=null,fixedFrom=null,fixedTo=null,fixedPort=null;
 if(line){index=+line.dataset.wire;state.selectedEdge=index;state.selected=null;state.selection.clear();mode='bend';render();}
 else if(handle){index=+handle.dataset.edge;mode=handle.dataset.wireEnd==='from'?'source':'target';const edge=model().edges[index];fixedFrom=edge.from;fixedTo=edge.to;fixedPort=edge.port;}
 else if(port.dataset.port==='out'){mode='target';fixedFrom=port.dataset.id;}
 else{fixedTo=port.dataset.id;fixedPort=port.dataset.port;const edgeIndex=model().edges.findIndex(e=>e.to===fixedTo&&e.port===fixedPort);if(edgeIndex>=0){index=edgeIndex;fixedFrom=model().edges[index].from;mode='target';}else mode='source';}
 const plane=$('#plane'),rect=plane.getBoundingClientRect(),scale=rect.width/820;
 const point=(x,y)=>({x:(x-rect.left)/scale,y:(y-rect.top)/scale});
 function move(e){if(Math.abs(e.clientX-start.x)+Math.abs(e.clientY-start.y)<4&&!moved)return;moved=true;const cursor=point(e.clientX,e.clientY);
  if(mode==='bend'){model().edges[index].bend={x:cursor.x,y:cursor.y};$('#plane').innerHTML=graphHTML(model());refreshIcons();return;}
  let a,b;
  if(mode==='target'){const source=model().nodes.find(n=>n.id===fixedFrom);a=outPoint(source);b=cursor;}
  else{const target=model().nodes.find(n=>n.id===fixedTo);a=cursor;b=fixedPort==='tap'?{x:target.x+nodeWidth(target)/2,y:target.y}:inPoint(target,fixedPort);}
  $('#connection-ghost')?.setAttribute('d',curve(a,b));
  $$('.port-drop-target').forEach(p=>p.classList.remove('port-drop-target'));
  const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-port]');if(hit&&(mode==='target'?hit.dataset.port!=='out':hit.dataset.port==='out'))hit.classList.add('port-drop-target');
 }
 function up(e){document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);document.removeEventListener('keydown',escape);$('#connection-ghost')?.setAttribute('d','');$$('.port-drop-target').forEach(p=>p.classList.remove('port-drop-target'));
  if(!moved){if(line){state.ignoreCanvasClickUntil=performance.now()+250;state.ignoreCanvasClickPoint={x:e.clientX,y:e.clientY};}return;}
  state.ignoreCanvasClickUntil=performance.now()+250;state.ignoreCanvasClickPoint={x:e.clientX,y:e.clientY};
  if(mode==='bend'){active().undo.push(before);active().redo=[];active().dirty=true;persist();render();return;}
  const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-port]');
  if(hit&&!hit.closest('.split-container')&&(mode==='target'?hit.dataset.port!=='out':hit.dataset.port==='out')){if(mode==='target')connectPorts(fixedFrom,hit.dataset.id,hit.dataset.port,index);else connectPorts(hit.dataset.id,fixedTo,fixedPort,index);}else toast('Connection unchanged · drop on a compatible named port');
  render();
 }
 function escape(e){if(e.key!=='Escape')return;document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);document.removeEventListener('keydown',escape);if(mode==='bend')active().model=before;render();}
 document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);document.addEventListener('keydown',escape);
});

boot();
